import{_ as a,c as i,o,ai as s}from"./chunks/framework.DMRKKuRm.js";const p=JSON.parse('{"title":"Reglas de Clientes","description":"","frontmatter":{},"headers":[],"relativePath":"Reglas/clientes.md","filePath":"Reglas/clientes.md"}'),t={name:"Reglas/clientes.md"};function r(n,e,l,d,c,u){return o(),i("div",null,e[0]||(e[0]=[s('<h1 id="reglas-de-clientes" tabindex="-1">Reglas de Clientes <a class="header-anchor" href="#reglas-de-clientes" aria-label="Permalink to &quot;Reglas de Clientes&quot;">​</a></h1><p>Reglas específicas sobre el uso de clientes, mods y recursos en SilkCraft Network.</p><h2 id="clientes-permitidos" tabindex="-1">Clientes Permitidos <a class="header-anchor" href="#clientes-permitidos" aria-label="Permalink to &quot;Clientes Permitidos&quot;">​</a></h2><h3 id="clientes-vanilla" tabindex="-1">Clientes Vanilla <a class="header-anchor" href="#clientes-vanilla" aria-label="Permalink to &quot;Clientes Vanilla&quot;">​</a></h3><ul><li>Minecraft Java Edition oficial</li><li>Minecraft Bedrock Edition oficial</li><li>Cualquier cliente vanilla sin modificaciones</li></ul><h3 id="clientes-modificados-permitidos" tabindex="-1">Clientes Modificados Permitidos <a class="header-anchor" href="#clientes-modificados-permitidos" aria-label="Permalink to &quot;Clientes Modificados Permitidos&quot;">​</a></h3><p>Los siguientes clientes están permitidos:</p><ul><li><strong>OptiFine</strong> - Mejoras de rendimiento</li><li><strong>Sodium</strong> - Mejoras de rendimiento</li><li><strong>Lunar Client</strong> - Cliente todo-en-uno</li><li><strong>Badlion Client</strong> - Cliente todo-en-uno</li><li><strong>Feather Client</strong> - Cliente ligero</li></ul><h2 id="mods-permitidos" tabindex="-1">Mods Permitidos <a class="header-anchor" href="#mods-permitidos" aria-label="Permalink to &quot;Mods Permitidos&quot;">​</a></h2><h3 id="mods-de-rendimiento" tabindex="-1">Mods de Rendimiento <a class="header-anchor" href="#mods-de-rendimiento" aria-label="Permalink to &quot;Mods de Rendimiento&quot;">​</a></h3><ul><li>OptiFine</li><li>Sodium</li><li>Lithium</li><li>Phosphor</li><li>Iris Shaders</li></ul><h3 id="mods-de-utilidad" tabindex="-1">Mods de Utilidad <a class="header-anchor" href="#mods-de-utilidad" aria-label="Permalink to &quot;Mods de Utilidad&quot;">​</a></h3><ul><li><strong>Minimap</strong> (solo waypoints, sin entidades)</li><li><strong>Inventory Tweaks</strong></li><li><strong>JEI/REI</strong> (solo visualización)</li><li><strong>WTHIT</strong> (What The Hell Is That)</li></ul><h3 id="mods-de-estetica" tabindex="-1">Mods de Estética <a class="header-anchor" href="#mods-de-estetica" aria-label="Permalink to &quot;Mods de Estética&quot;">​</a></h3><ul><li>Shaders (solo visual)</li><li>Texture packs</li><li>Sound mods</li></ul><h2 id="clientes-y-mods-prohibidos" tabindex="-1">Clientes y Mods Prohibidos <a class="header-anchor" href="#clientes-y-mods-prohibidos" aria-label="Permalink to &quot;Clientes y Mods Prohibidos&quot;">​</a></h2><h3 id="hacks-cheats-prohibidos" tabindex="-1">Hacks/Cheats Prohibidos <a class="header-anchor" href="#hacks-cheats-prohibidos" aria-label="Permalink to &quot;Hacks/Cheats Prohibidos&quot;">​</a></h3><p>Está <strong>estrictamente prohibido</strong> el uso de:</p><ul><li><strong>X-Ray</strong> - Ver a través de bloques</li><li><strong>Fly</strong> - Volar sin permiso</li><li><strong>Speed</strong> - Movimiento aumentado</li><li><strong>Kill Aura</strong> - Ataque automático</li><li><strong>Reach</strong> - Alcance aumentado</li><li><strong>Auto Clicker</strong> - Click automático</li><li><strong>ESP</strong> - Ver entidades a través de bloques</li><li><strong>No Fall</strong> - No recibir daño por caída</li><li><strong>Anti Knockback</strong> - No recibir retroceso</li><li><strong>Auto Armor</strong> - Equipar armadura automáticamente</li><li><strong>Auto Potion</strong> - Usar pociones automáticamente</li></ul><h3 id="clientes-prohibidos" tabindex="-1">Clientes Prohibidos <a class="header-anchor" href="#clientes-prohibidos" aria-label="Permalink to &quot;Clientes Prohibidos&quot;">​</a></h3><p>Los siguientes clientes están prohibidos:</p><ul><li><strong>Wurst</strong> - Cliente de hacks</li><li><strong>Impact</strong> - Cliente de hacks</li><li><strong>Aristois</strong> - Cliente de hacks</li><li>Cualquier cliente con hacks integrados</li></ul><h2 id="deteccion-y-sanciones" tabindex="-1">Detección y Sanciones <a class="header-anchor" href="#deteccion-y-sanciones" aria-label="Permalink to &quot;Detección y Sanciones&quot;">​</a></h2><h3 id="sistema-anti-cheat" tabindex="-1">Sistema Anti-Cheat <a class="header-anchor" href="#sistema-anti-cheat" aria-label="Permalink to &quot;Sistema Anti-Cheat&quot;">​</a></h3><p>El servidor utiliza un sistema anti-cheat avanzado que detecta:</p><ul><li>Movimientos anormales</li><li>Interacciones imposibles</li><li>Uso de hacks conocidos</li></ul><h3 id="sanciones-por-hacks" tabindex="-1">Sanciones por Hacks <a class="header-anchor" href="#sanciones-por-hacks" aria-label="Permalink to &quot;Sanciones por Hacks&quot;">​</a></h3><ul><li><strong>Primera detección:</strong> Ban de 7 días</li><li><strong>Segunda detección:</strong> Ban de 30 días</li><li><strong>Tercera detección:</strong> Ban permanente</li></ul><h3 id="apelaciones" tabindex="-1">Apelaciones <a class="header-anchor" href="#apelaciones" aria-label="Permalink to &quot;Apelaciones&quot;">​</a></h3><p>Si crees que fuiste baneado injustamente por el anti-cheat:</p><ol><li>Únete a nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a></li><li>Ve al canal de apelaciones</li><li>Explica tu situación</li><li>Proporciona evidencia si es necesario</li></ol><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas Frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas Frecuentes&quot;">​</a></h2><h3 id="¿puedo-usar-optifine" tabindex="-1">¿Puedo usar OptiFine? <a class="header-anchor" href="#¿puedo-usar-optifine" aria-label="Permalink to &quot;¿Puedo usar OptiFine?&quot;">​</a></h3><p>Sí, OptiFine está permitido.</p><h3 id="¿puedo-usar-un-minimap" tabindex="-1">¿Puedo usar un minimap? <a class="header-anchor" href="#¿puedo-usar-un-minimap" aria-label="Permalink to &quot;¿Puedo usar un minimap?&quot;">​</a></h3><p>Sí, pero solo si no muestra entidades (jugadores, mobs). Solo waypoints están permitidos.</p><h3 id="¿puedo-usar-shaders" tabindex="-1">¿Puedo usar shaders? <a class="header-anchor" href="#¿puedo-usar-shaders" aria-label="Permalink to &quot;¿Puedo usar shaders?&quot;">​</a></h3><p>Sí, los shaders son solo visuales y están permitidos.</p><h3 id="¿puedo-usar-un-auto-clicker-para-construir" tabindex="-1">¿Puedo usar un auto-clicker para construir? <a class="header-anchor" href="#¿puedo-usar-un-auto-clicker-para-construir" aria-label="Permalink to &quot;¿Puedo usar un auto-clicker para construir?&quot;">​</a></h3><p>No, los auto-clickers están prohibidos incluso para construcción.</p><h3 id="¿que-pasa-si-mi-cliente-tiene-hacks-pero-no-los-uso" tabindex="-1">¿Qué pasa si mi cliente tiene hacks pero no los uso? <a class="header-anchor" href="#¿que-pasa-si-mi-cliente-tiene-hacks-pero-no-los-uso" aria-label="Permalink to &quot;¿Qué pasa si mi cliente tiene hacks pero no los uso?&quot;">​</a></h3><p>Si tu cliente tiene hacks integrados, no puedes usarlo en el servidor, incluso si no activas los hacks.</p><h3 id="¿puedo-usar-macros" tabindex="-1">¿Puedo usar macros? <a class="header-anchor" href="#¿puedo-usar-macros" aria-label="Permalink to &quot;¿Puedo usar macros?&quot;">​</a></h3><p>Macros simples para construcción pueden estar permitidas, pero macros para PvP o combate están prohibidas. Consulta con un administrador si no estás seguro.</p><hr><p><strong>Nota:</strong> Cuando tengas dudas sobre si un mod o cliente está permitido, es mejor preguntar a un administrador antes de usarlo. La ignorancia no es excusa para evitar sanciones.</p><p>Para más información, consulta <a href="/Reglas/normativa-general.html">Normativa General</a> o contacta a un administrador en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a>.</p>',47)]))}const m=a(t,[["render",r]]);export{p as __pageData,m as default};
